 private final Paint p=new Paint(1);private final Random rng=new Random();private GameState s;private final ReactionController reactions=new ReactionController();private final GameplayReactionEvents gameplayReactions=new GameplayReactionEvents(reactions);private HouseReactionEvents houseReactions;private int screen=0,selectedLevel=1,lastHatch=-1,taps=0,misses=0,levelPage=0,albumPage=0,achievementPage=0,challengeScore=0;private long challengeStartedAt=0L;private float targetX=.5f,targetY=.5f;private String reaction="";
