 private void album(Canvas c,float w,float h){ReleaseCandidateVisuals.drawCollectionBackdrop(c,p,w,h,s.collectionCount(),s.favoriteMonster);CollectionRewardCatalog.Card[] rewards=CollectionRewardCatalog.snapshot(s,getContext());int claimable=0;for(CollectionRewardCatalog.Card r:rewards)if(r.claimable)claimable++;top(c,"📖 COLEÇÃO "+s.collectionCount()+"/32",w);AlbumGridVisuals.drawPage(c,p,w,h,albumPage,s.ownedMask,s.favoriteMonster);button(c,"PÁGINA",w*.06f,h*.82f,w*.31f,h*.90f,BLUE);button(c,claimable>0?"🎁 RESGATAR":"🎁 PRÊMIOS",w*.34f,h*.82f,w*.66f,h*.90f,claimable>0?GOLD:GREEN);button(c,"VOLTAR",w*.69f,h*.82f,w*.94f,h*.90f,PURPLE);if(claimable>0)text(c,"Você tem recompensa do álbum!",w*.12f,h*.95f,15,NAVY);}
 private void hatchReveal(Canvas c,float w,float h){top(c,"🥚 NOVO MONSTRINHO!",w);box(c,w*.08f,h*.18f,w*.92f,h*.78f,CREAM);mascot(c,w*.5f,h*.43f,1.35f,lastHatch>=24?GOLD:PURPLE);p.setTextAlign(Paint.Align.CENTER);text(c,lastHatch>=24?"RARO! ✨":"DESCOBERTA!",w*.5f,h*.64f,26,lastHatch>=24?0xffc77700:NAVY);text(c,"Monstrinho #"+(lastHatch+1),w*.5f,h*.70f,20,NAVY);p.setTextAlign(Paint.Align.LEFT);button(c,"VER NO ÁLBUM",w*.10f,h*.82f,w*.52f,h*.92f,BLUE);button(c,"CONTINUAR",w*.56f,h*.82f,w*.90f,h*.92f,GREEN);}
 private void achievements(Canvas c,float w,float h){ReleaseCandidateVisuals.drawAchievementBackdrop(c,p,w,h,s.achievementCount());AchievementCatalog.Card[] cards=AchievementCatalog.snapshot(getContext());top(c,"🏆 CONQUISTAS "+s.achievementCount()+"/8",w);int start=achievementPage*4;for(int i=0;i<4&&start+i<cards.length;i++){AchievementCatalog.Card a=cards[start+i];float y=h*(.19f+i*.15f);box(c,w*.06f,y,w*.94f,y+h*.12f,a.unlocked?0xffffefb0:Color.WHITE);text(c,(a.unlocked?"✓ ":"☆ ")+a.title,w*.10f,y+h*.045f,17,NAVY);text(c,a.unlocked?"Desbloqueada":a.current+" / "+a.target+"  •  "+a.percent+"%",w*.10f,y+h*.085f,14,a.unlocked?0xff31844b:PURPLE);}button(c,achievementPage==0?"PRÓXIMAS":"ANTERIORES",w*.08f,h*.84f,w*.48f,h*.93f,BLUE);button(c,"VOLTAR",w*.52f,h*.84f,w*.92f,h*.93f,PURPLE);}
 private void house(Canvas c,float w,float h){ReleaseCandidateVisuals.drawHouseBackdrop(c,p,w,h,s.houseLevel);top(c,"🏡 CASINHA",w);p.setColor(0xfff3b45a);c.drawRect(w*.22f,h*.33f,w*.78f,h*.63f,p);Path roof=new Path();roof.moveTo(w*.14f,h*.35f);roof.lineTo(w*.5f,h*.20f);roof.lineTo(w*.86f,h*.35f);roof.close();p.setColor(0xffd95f4d);c.drawPath(roof,p);mascot(c,w*.5f,h*.67f,.65f,BLUE);box(c,w*.08f,h*.12f,w*.92f,h*.19f,0xddffffff);text(c,s.houseStage()+" • Nível "+s.houseLevel+" • Tema "+s.decorName(),w*.11f,h*.155f,15,NAVY);text(c,s.houseLevel>=5?"Casinha no nível máximo 👑":"Próxima evolução: "+(40*s.houseLevel)+" moedas • "+s.houseNextCare()+" carinho(s)",w*.11f,h*.185f,13,PURPLE);button(c,"❤ CARINHO",w*.08f,h*.75f,w*.46f,h*.84f,0xffff7597);button(c,"⬆ EVOLUIR",w*.54f,h*.75f,w*.92f,h*.84f,GREEN);button(c,"🎨 TEMA",w*.08f,h*.87f,w*.46f,h*.96f,GOLD);button(c,"VOLTAR",w*.54f,h*.87f,w*.92f,h*.96f,PURPLE);}
